-- Nakama demo data. NOT part of the migrations: run it by hand when you want a realistic database to explore.
--
-- Contents: the two login accounts, 20 more users, 15 chatbots with their documents and team, 10 formations with
-- their enrollments, 72 conversations and the read models that go with them (summaries, details, history,
-- audit log, analytics).
--
-- Accounts: admin@nakama.com (administrator) and user@nakama.com, both with password Admin123.
-- The other users live under @seed.nakama.test and use the password Seed1234.
--
-- Usage, once the API has applied the migrations:
--   docker exec -i nakama-postgres psql -U nakama -d nakama < docs/db/demo-data.sql
--
-- It can be run more than once: rows that already exist are skipped.

BEGIN;

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
















